import json, sys
sys.path.insert(0, '.')
from spec import SEEDS, GROUPS, DROPPED
F = {f['fid']: f for f in json.load(open('../findings_flat.json'))}
used = {}
for g in GROUPS:
    for m in g['members']:
        if m in used: print("DUP member", m, used[m], g['id'])
        used[m] = g['id']
dropped = {d[0] for d in DROPPED}
