        fh.write(f"## {g['id']} {g['slug']} [{g['queue']}, {g['sev']}, {g['kind']}]\n{g['title']}\n\n- members: {', '.join(g['members'])}\n- files: {g['files']}\n- fix strategy: {g['fix']}\n- test approach: {g['test']}\n\n")
